  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}
.menu-item-name { padding: 12px 12px 4px; font-weight: 600; font-size: 0.9rem; color: var(--forest); }
.menu-item-cal { font-size: 0.8rem; color: var(--gray-400); }

@media (max-width: 768px) {
  .menu-layout { flex-direction: column; }
  .menu-sidebar { flex: none; position: static; display: flex; overflow-x: auto; gap: 8px; padding-bottom: 16px; max-height: none; }
  .sidebar-group { margin-bottom: 0; display: flex; gap: 4px; flex-shrink: 0; }
  .sidebar-group-title { display: none; }
  .sidebar-link { white-space: nowrap; padding: 8px 16px; border: 1px solid var(--gray-200); border-radius: 50px; font-size: 0.85rem; }
  .menu-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ===== Rewards ===== */
.rewards-hero {
  background: linear-gradient(135deg, var(--green) 0%, var(--forest) 100%);
  color: var(--white);
  padding: 80px 0;
  text-align: center;
}
.rewards-hero h1 { color: var(--white); font-size: 3rem; margin-bottom: 16px; }
.rewards-hero p { font-size: 1.1rem; margin-bottom: 32px; opacity: 0.9; max-width: 600px; margin-left: auto; margin-right: auto; }

.how-it-works { padding: 80px 0; }
.steps-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; text-align: center; }
.step-card { padding: 32px; }
.step-icon {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--cream-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.8rem;
  margin: 0 auto 20px;
  color: var(--green);
}
.step-card h3 { font-size: 1.3rem; margin-bottom: 12px; }
.step-card p { color: var(--gray-500); font-size: 0.95rem; }

@media (max-width: 768px) {
  .steps-grid { grid-template-columns: 1fr; gap: 24px; }
  .rewards-hero h1 { font-size: 2rem; }
}

/* ===== Tier Cards ===== */
.tiers-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.tier-card {
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  background: var(--white);
  box-shadow: var(--shadow-md);
  text-align: center;
  border-top: 4px solid var(--green);
  transition: transform var(--transition);
}
.tier-card:hover { transform: translateY(-4px); }
.tier-card.gold { border-top-color: #D4A843; }
.tier-card.reserve { border-top-color: var(--brown); }
.tier-badge {
  display: inline-block;
  padding: 6px 18px;
  border-radius: 50px;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
}
.tier-card .tier-badge { background: #E6F5ED; color: var(--green); }
.tier-card.gold .tier-badge { background: #FDF5E3; color: #9A7A1C; }
.tier-card.reserve .tier-badge { background: #F3EDE8; color: var(--brown); }
.tier-threshold { font-size: 1.6rem; font-weight: 700; margin-bottom: 20px; color: var(--forest); }
.tier-benefits { list-style: none; text-align: left; }
.tier-benefits li { padding: 8px 0; font-size: 0.92rem; color: var(--gray-600); border-bottom: 1px solid var(--gray-100); display: flex; gap: 8px; align-items: flex-start; }
.tier-benefits li::before { content: '\2713'; color: var(--green); font-weight: 700; flex-shrink: 0; }

@media (max-width: 768px) {
  .tiers-grid { grid-template-columns: 1fr; }
}

/* ===== Redemption Panel ===== */
.redemption-panel {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 36px;
  box-shadow: var(--shadow-md);
}
.redemption-content { display: flex; align-items: center; gap: 32px; }
.redemption-icon {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--cream-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  flex-shrink: 0;
}
.redemption-info h3 { font-size: 1.3rem; margin-bottom: 8px; }
.redemption-info p { color: var(--gray-500); }
.redemption-value {
  margin-left: auto;
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--green);
  white-space: nowrap;
}

@media (max-width: 768px) {
  .redemption-content { flex-direction: column; text-align: center; }
  .redemption-value { margin-left: 0; margin-top: 8px; }
}

/* ===== Partnerships ===== */
.partners-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 28px; }
.partner-card {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 28px;
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}
.partner-logo {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-md);
  background: var(--cream-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  flex-shrink: 0;
}
.partner-info h4 { font-family: var(--font-body); font-size: 1rem; margin-bottom: 4px; }
.partner-info p { font-size: 0.88rem; color: var(--gray-500); }

@media (max-width: 768px) {
  .partners-grid { grid-template-columns: 1fr; }
}

/* ===== Gift ===== */
.gift-hero {
  background: linear-gradient(135deg, var(--cream) 0%, var(--cream-light) 100%);
  padding: 80px 0;
  text-align: center;
}
.gift-hero h1 { font-size: 2.8rem; margin-bottom: 16px; }
.gift-hero p { color: var(--gray-600); max-width: 550px; margin: 0 auto 32px; font-size: 1.05rem; }
.category-section { margin-bottom: 48px; }
.category-section h3 { font-size: 1.5rem; margin-bottom: 20px; }

/* ===== Store Locator ===== */
.locator-layout { display: flex; height: calc(100vh - 73px); }
.locator-panel {
  flex: 0 0 420px;
  display: flex;
  flex-direction: column;
  background: var(--white);
  border-right: 1px solid var(--gray-200);
}
.locator-search { padding: 20px; border-bottom: 1px solid var(--gray-200); }
.search-bar {
  display: flex;
  gap: 8px;
  align-items: center;
  background: var(--gray-50);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 4px 4px 4px 16px;
  transition: border-color var(--transition);
}
.search-bar:focus-within { border-color: var(--green); }
.search-bar input {
  flex: 1;
  border: none;
  background: transparent;
  font-size: 0.95rem;
  padding: 10px 0;
  outline: none;
  font-family: var(--font-body);
}
.search-bar button {
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  border: none;
  background: var(--green);
  color: var(--white);
  font-weight: 600;
  font-size: 0.88rem;
}
.order-toggle { display: flex; gap: 8px; margin-top: 12px; }
.order-toggle button {
  flex: 1;
  padding: 10px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  background: var(--white);
  font-weight: 600;
  font-size: 0.88rem;
  color: var(--gray-500);
  transition: all var(--transition);
}
.order-toggle button.active { border-color: var(--green); background: var(--green); color: var(--white); }
.filter-bar { display: flex; gap: 8px; margin-top: 12px; flex-wrap: wrap; }
.filter-btn {
  padding: 6px 14px;
  border-radius: 50px;
  border: 1px solid var(--gray-200);
  background: var(--white);
  font-size: 0.82rem;
  color: var(--gray-600);
  font-weight: 500;
  transition: all var(--transition);
}
.filter-btn:hover, .filter-btn.active { border-color: var(--green); color: var(--green); background: #E6F5ED; }
.store-results { flex: 1; overflow-y: auto; }
.store-card {
  padding: 20px;
  border-bottom: 1px solid var(--gray-100);
  cursor: pointer;
  transition: background var(--transition);
}
.store-card:hover { background: var(--gray-50); }
.store-card h4 { font-family: var(--font-body); font-weight: 600; margin-bottom: 4px; color: var(--forest); }
.store-card p { font-size: 0.85rem; color: var(--gray-500); margin-bottom: 4px; }
.store-features { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }
.store-feature {
  padding: 3px 10px;
  border-radius: 50px;
  background: var(--cream-light);
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--brown-light);
}
.map-area {
  flex: 1;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.map-placeholder {
  text-align: center;
  color: var(--gray-400);
}
.map-placeholder-icon { font-size: 4rem; margin-bottom: 16px; }
.map-placeholder p { font-size: 1rem; }

@media (max-width: 768px) {
  .locator-layout { flex-direction: column; height: auto; }
  .locator-panel { flex: none; }
  .map-area { height: 300px; }
}

/* ===== Breadcrumb ===== */
.breadcrumb {
  padding: 16px 0;
  font-size: 0.85rem;
  color: var(--gray-400);
}
.breadcrumb a { color: var(--gray-500); }
.breadcrumb span { margin: 0 8px; }

/* ===== App Download ===== */
.app-cta {
  background: var(--forest);
  color: var(--white);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: flex;
  align-items: center;
  gap: 40px;
}
.app-cta-content { flex: 1; }
.app-cta-content h2 { color: var(--white); font-size: 2rem; margin-bottom: 12px; }
.app-cta-content p { color: var(--gray-300); margin-bottom: 24px; }
.app-badges { display: flex; gap: 12px; }
.app-badge {
  padding: 10px 20px;
  background: rgba(255,255,255,0.15);
  border-radius: var(--radius-sm);
  color: var(--white);
  font-weight: 600;
  font-size: 0.88rem;
  transition: background var(--transition);
}
.app-badge:hover { background: rgba(255,255,255,0.25); color: var(--white); }
.app-cta-img {
  flex: 0 0 200px;
  height: 200px;
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
}

@media (max-width: 768px) {
  .app-cta { flex-direction: column; padding: 32px; text-align: center; }
  .app-badges { justify-content: center; }
  .app-cta-img { flex: none; width: 140px; height: 140px; font-size: 3rem; }
}

/* ===== Business Gifting ===== */
.biz-banner {
  display: flex;
  align-items: center;
  gap: 40px;
  padding: 48px;
  background: var(--cream-light);
  border-radius: var(--radius-xl);
}
.biz-banner-img {
  flex: 0 0 240px;
  height: 200px;
  background: var(--cream);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
}
.biz-banner-content { flex: 1; }
.biz-banner-content h2 { font-size: 1.8rem; margin-bottom: 12px; }
.biz-banner-content p { color: var(--gray-600); margin-bottom: 20px; }

@media (max-width: 768px) {
  .biz-banner { flex-direction: column; padding: 28px; }
  .biz-banner-img { flex: none; width: 100%; height: 160px; }
}

/* ===== FAQ ===== */
.faq-list { max-width: 750px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--gray-200);
}
.faq-question {
  width: 100%;
  background: none;
  border: none;
  padding: 20px 0;
  text-align: left;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--forest);
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-question::after { content: '+'; font-size: 1.3rem; color: var(--green); transition: transform var(--transition); }
.faq-item.open .faq-question::after { content: '\2212'; }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.faq-answer-inner { padding: 0 0 20px; color: var(--gray-600); font-size: 0.95rem; line-height: 1.7; }
.faq-item.open .faq-answer { max-height: 300px; }

/* ===== Utility classes ===== */
.mb-0 { margin-bottom: 0; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-40 { margin-bottom: 40px; }
.mb-60 { margin-bottom: 60px; }
.mt-40 { margin-top: 40px; }
.mt-60 { margin-top: 60px; }

/* ===== Animations ===== */
@keyframes slideUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-in { animation: slideUp 0.6s ease forwards; }
